SELECT (NOT $8 AND NOT EXISTS ( SELECT 1 FROM crm_companies c JOIN crm_domains d ON d.company_id = c.id WHERE c.team_id = $1 AND d.team_id = $1 AND LOWER(d.domain) = $3 )) OR EXISTS ( SELECT 1 FROM crm_companies c JOIN crm_domains d ON d.company_id = c.id JOIN crm_contacts ct ON ct.company_id = c.id JOIN crm_contact_sources s ON s.contact_id = ct.id WHERE c.team_id = $1 AND d.team_id = $1 AND LOWER(d.domain) = $3 AND ct.email = $4 AND s.link_id = $2 AND (ct.name IS NOT NULL OR $5::text IS NULL) AND c.last_interaction >= $7 AND ct.last_interaction >= $7 AND (NOT $8 OR (c.first_interaction <= $6 AND ct.first_interaction <= $6)) FOR KEY SHARE OF s ) AS "changes_nothing!"
